INSERT INTO site_settings (key, value) VALUES ('name', 'Akeva Care Sérénité 24');
INSERT INTO site_settings (key, value) VALUES ('shortName', 'Akeva Care');
INSERT INTO site_settings (key, value) VALUES ('tagline', 'Prendre soin de vos proches, même lorsque vous ne pouvez pas être là.');
INSERT INTO site_settings (key, value) VALUES ('promise', 'Un accompagnement professionnel et humain à domicile et à l''hôpital.');
INSERT INTO site_settings (key, value) VALUES ('description', 'Akeva Care Sérénité 24 accompagne les personnes âgées, les personnes dépendantes et les patients à domicile ou à l''hôpital à Yaoundé et Douala. Présence professionnelle, humaine et personnalisée.');
INSERT INTO site_settings (key, value) VALUES ('url', 'https://akevacare.cm');
INSERT INTO site_settings (key, value) VALUES ('email', 'contact@akevacare.cm');
INSERT INTO site_settings (key, value) VALUES ('phoneDisplay', '+237 6 99 00 24 24');
INSERT INTO site_settings (key, value) VALUES ('phoneTel', '+237699002424');
INSERT INTO site_settings (key, value) VALUES ('whatsapp', '237699002424');
INSERT INTO site_settings (key, value) VALUES ('cities', '["Yaoundé","Douala"]');
